echo "# loop: put the six preflight records where the publisher pushes them, for developing the dataset builder"; W=~/work/loop; mkdir -p $W/pub/pf-stu/episodes $W/pub/pf-self/episodes; cp $W/runs/pf-stu/episodes/* $W/pub/pf-stu/episodes/; cp $W/runs/pf-self/episodes/* $W/pub/pf-self/episodes/; ls -la $W/pub/pf-stu/episodes $W/pub/pf-self/episodes | grep json | wc -l; wc -l < $W/runs/s0/results.jsonl; tail -n 1 $W/runs/s0.log | cut -c1-160; git -C $W/pub log -1 --format="publisher last pushed %cd" --date=format:"%H:%M:%S UTC"; date -u +%T
